class Solution {
    public boolean checkRecord(String s) {
        int absences = 0;
        int lateStreak = 0;
        for (int i = 0; i < s.length(); i++) {
            char day = s.charAt(i);
            if (day == 'A') {
                absences++;
                lateStreak = 0;
                if (absences >= 2) {
                    return false;
                }
            } else if (day == 'L') {
                lateStreak++;
                if (lateStreak >= 3) {
                    return false;
                }
            } else {
                lateStreak = 0;
            }
        }
        return true;
    }
}

class Solution {
    public boolean checkRecord(String s) {
        boolean fewerThanTwoAbsences = s.indexOf('A') == s.lastIndexOf('A');
        boolean noThreeLateStreak = !s.contains("LLL");
        return fewerThanTwoAbsences && noThreeLateStreak;
    }
}

class Solution {
    public boolean checkRecord(String s) {
        boolean[][] reachable = new boolean[2][3];
        reachable[0][0] = true;
        for (int i = 0; i < s.length(); i++) {
            boolean[][] next = new boolean[2][3];
            char day = s.charAt(i);
            for (int absences = 0; absences < 2; absences++) {
                for (int late = 0; late < 3; late++) {
                    if (!reachable[absences][late]) {
                        continue;
                    }
                    if (day == 'P') {
                        next[absences][0] = true;
                    } else if (day == 'A') {
                        if (absences + 1 < 2) {
                            next[absences + 1][0] = true;
                        }
                    } else if (late + 1 < 3) {
                        next[absences][late + 1] = true;
                    }
                }
            }
            reachable = next;
        }
        for (int absences = 0; absences < 2; absences++) {
            for (int late = 0; late < 3; late++) {
                if (reachable[absences][late]) {
                    return true;
                }
            }
        }
        return false;
    }
}

class Solution {
    public boolean checkRecord(String s) {
        return !s.matches(".*A.*A.*|.*LLL.*");
    }
}
